BEGIN;
create temp table checks(label text);
create function pg_temp.check(passed boolean,label text) returns void language plpgsql as $$begin if passed is not true then raise exception 'FAIL: %',label;end if;insert into checks values(label);end$$;
create function pg_temp.fixture() returns jsonb language plpgsql as $$declare p uuid:=gen_random_uuid();c uuid:=gen_random_uuid();actor uuid;identity jsonb;
begin
 select id into actor from public.profiles where org_id='22222222-2222-2222-2222-222222222222' order by id limit 1;
 insert into public.properties(id,name,org_id)values(p,'Email credential SQL fixture','22222222-2222-2222-2222-222222222222');
 insert into public.email_configurations(id,property_id,profile_id,provider,google_email,account_email,access_token,refresh_token,token_expires_at,sync_enabled,token_status,scopes,provider_metadata)values(c,p,actor,'microsoft','fixture@example.invalid','fixture@example.invalid','old-access','old-refresh',now()-interval '1 minute',true,'healthy',array['User.Read','Calendars.ReadWrite','Mail.Send','Mail.Read'],'{"scopeEvidence":"provider_response"}');
 select public.email_credential_identity(ac) into identity from public.email_configurations ac where id=c;
 return jsonb_build_object('p',p,'c',c,'actor',actor,'identity',identity);
end$$;
create function pg_temp.claim(f jsonb,id uuid,version bigint default 1) returns jsonb language sql as $$select public.claim_email_token_refresh((f->>'p')::uuid,(f->>'c')::uuid,version,f->'identity',id,true)$$;
create function pg_temp.finish(f jsonb,id uuid,outcome text,tokens jsonb default null) returns jsonb language sql as $$select public.finish_email_token_refresh((f->>'p')::uuid,(f->>'c')::uuid,id,outcome,tokens)$$;
DO $$declare f jsonb;r jsonb;attempt uuid;decision uuid;tokens jsonb;v bigint;
begin
 tokens:=jsonb_build_object('accessToken','new-access','refreshToken','rotated-refresh','expiresAt',now()+interval '1 hour');
 f:=pg_temp.fixture();attempt:=gen_random_uuid();r:=pg_temp.claim(f,attempt);
 perform pg_temp.check(r->>'state'='claimed' and r->>'refreshToken'='old-refresh','claim returns current private credential');
 perform pg_temp.check(pg_temp.claim(f,attempt)->>'state'='busy','same claim cannot repeat OAuth exchange');
 perform pg_temp.check(pg_temp.claim(f,gen_random_uuid())->>'state'='busy','concurrent refresh serialized');
 r:=pg_temp.finish(f,attempt,'success',tokens);
 perform pg_temp.check(r->>'state'='saved' and r->>'version'='2','saved tokens acknowledged with new version');
 perform pg_temp.check((select access_token='new-access' and refresh_token='rotated-refresh' and credential_version=2 from public.email_configurations where id=(f->>'c')::uuid),'rotated refresh credential persisted');
 perform pg_temp.check((select refresh_status='success' and completed_version=2 and new_expires_at>now() and result_hash is not null from public.email_token_refreshes where request_id=attempt),'success and audit commit together');
 perform pg_temp.check(pg_temp.finish(f,attempt,'success',tokens)->>'state'='saved','lost save response replays safely');
 perform pg_temp.check((select credential_version=2 from public.email_configurations where id=(f->>'c')::uuid),'save replay does not bump version');
 perform pg_temp.check(pg_temp.finish(f,attempt,'success',tokens||'{"accessToken":"different"}')->>'state'='request_conflict','same attempt cannot save different result');
 perform pg_temp.check(pg_temp.claim(f,gen_random_uuid())->>'state'='ready','stale request reuses a fresh same-account version');
 perform pg_temp.check((select count(*)=1 from public.email_token_refreshes where email_configuration_id=(f->>'c')::uuid),'reused version does not create another attempt');
 update public.email_configurations set signature_template='Fixture signature',credential_version=900 where id=(f->>'c')::uuid;
 perform pg_temp.check((select credential_version=2 from public.email_configurations where id=(f->>'c')::uuid),'ordinary settings do not change credential version and cannot forge it');
 f:=pg_temp.fixture();attempt:=gen_random_uuid();perform pg_temp.claim(f,attempt);r:=pg_temp.finish(f,attempt,'success',tokens-'refreshToken');
 perform pg_temp.check((select refresh_token='old-refresh' from public.email_configurations where id=(f->>'c')::uuid),'Google omitted refresh token preserves stored token');
 f:=pg_temp.fixture();attempt:=gen_random_uuid();perform pg_temp.claim(f,attempt);decision:=gen_random_uuid();
 r:=public.disconnect_recorded_email((f->>'p')::uuid,(f->>'actor')::uuid,decision,'microsoft');
 perform pg_temp.check(r->>'state'='applied' and r->>'disconnected'='1','operator disconnect acknowledged');
 perform pg_temp.check((select access_token is null and refresh_token is null and not sync_enabled and credential_version=2 from public.email_configurations where id=(f->>'c')::uuid),'disconnect clears credentials and invalidates revision');
 perform pg_temp.check(pg_temp.finish(f,attempt,'success',tokens)->>'state'='connection_changed','late refresh cannot resurrect disconnect');
 perform pg_temp.check(pg_temp.finish(f,attempt,'revoked')->>'state'='connection_changed','late invalid-grant cannot change disconnect');
 perform pg_temp.check((select phase='succeeded' and product='integrations' and not training_eligible and before_state::text not like '%old-refresh%' and after_state::text not like '%old-access%' from public.shared_action_events where id=decision),'disconnect evidence excludes credentials and training');
 perform pg_temp.check(public.disconnect_recorded_email((f->>'p')::uuid,(f->>'actor')::uuid,decision,'microsoft')->>'state'='replayed','disconnect lost response recovers one action');
 perform pg_temp.check(public.disconnect_recorded_email((f->>'p')::uuid,(f->>'actor')::uuid,decision,'google')->>'state'='request_conflict','disconnect cannot reuse identity for different provider');
 perform pg_temp.check(pg_temp.claim(f,gen_random_uuid())->>'state'='reconnect_required','disabled calendar cannot refresh');
 f:=pg_temp.fixture();attempt:=gen_random_uuid();perform pg_temp.claim(f,attempt);
 update public.email_configurations set access_token='reconnected',refresh_token='new-consent',token_expires_at=now()+interval '2 hours' where id=(f->>'c')::uuid;
 perform pg_temp.check(pg_temp.finish(f,attempt,'revoked')->>'state'='connection_changed','stale invalid-grant cannot revoke renewed consent');
 perform pg_temp.check((select token_status='healthy' and access_token='reconnected' from public.email_configurations where id=(f->>'c')::uuid),'new consent survives older failed exchange');
 f:=pg_temp.fixture();attempt:=gen_random_uuid();perform pg_temp.claim(f,attempt);perform pg_temp.finish(f,attempt,'temporary_failure');
 perform pg_temp.check(pg_temp.claim(f,gen_random_uuid())->>'state'='retry_later','provider failure retries have a cooldown');
 update public.email_token_refreshes set finished_at=now()-interval '1 minute' where request_id=attempt;
 perform pg_temp.check(pg_temp.claim(f,gen_random_uuid())->>'state'='claimed','explicit failure can retry after cooldown');
 f:=pg_temp.fixture();attempt:=gen_random_uuid();perform pg_temp.claim(f,attempt);perform pg_temp.finish(f,attempt,'unconfirmed');
 perform pg_temp.check((select token_status='refresh_unconfirmed' from public.email_configurations where id=(f->>'c')::uuid),'uncertain exchange requires reconnect');
 perform pg_temp.check(pg_temp.claim(f,gen_random_uuid())->>'state'='reconnect_required','ambiguous request is never blindly replayed');
 f:=pg_temp.fixture();attempt:=gen_random_uuid();perform pg_temp.claim(f,attempt);update public.email_token_refreshes set lease_until=now()-interval '1 minute' where request_id=attempt;
 perform pg_temp.check(pg_temp.claim(f,gen_random_uuid())->>'state'='refresh_unconfirmed','abandoned lease becomes visible review');
 perform pg_temp.check((select refresh_status='review' and error_message='refresh_unconfirmed' from public.email_token_refreshes where request_id=attempt),'interruption recorded without token data');
 perform pg_temp.check(pg_temp.finish(f,attempt,'success',tokens)->>'state'='saved','late exact result can recover the same unchanged interrupted attempt');
 f:=pg_temp.fixture();attempt:=gen_random_uuid();perform pg_temp.claim(f,attempt);perform pg_temp.finish(f,attempt,'revoked');
 perform pg_temp.check((select token_status='revoked' from public.email_configurations where id=(f->>'c')::uuid),'structured invalid grant requires reauthorization');
 f:=pg_temp.fixture();
 perform pg_temp.check(pg_temp.claim(jsonb_set(f,'{identity,accountEmail}','"different@example.invalid"'),gen_random_uuid())->>'state'='connection_changed','account identity is pinned');
 perform pg_temp.check(pg_temp.claim(jsonb_set(f,'{p}',to_jsonb(gen_random_uuid())),gen_random_uuid())->>'state'='not_found','wrong-property credential access rejected');
 perform pg_temp.check(public.disconnect_recorded_email((f->>'p')::uuid,gen_random_uuid(),gen_random_uuid(),'microsoft')->>'state'='forbidden','disconnect membership rechecked in transaction');
 perform pg_temp.check(not has_table_privilege('authenticated','public.email_configurations','SELECT'),'browser cannot read credential rows');
 perform pg_temp.check(not has_table_privilege('authenticated','public.email_configurations','UPDATE'),'browser cannot bypass credential operations');
 perform pg_temp.check(not has_function_privilege('authenticated','public.claim_email_token_refresh(uuid,uuid,bigint,jsonb,uuid,boolean)','EXECUTE'),'credential claim service-only');
 perform pg_temp.check(not has_function_privilege('anon','public.finish_email_token_refresh(uuid,uuid,uuid,text,jsonb)','EXECUTE'),'credential finalization service-only');
end$$;
create function pg_temp.reject_audit() returns trigger language plpgsql as $$begin if new.refresh_status='success' then raise exception 'Fixture audit failure';end if;return new;end$$;
create trigger fixture_audit_failure before update on public.email_token_refreshes for each row execute function pg_temp.reject_audit();
DO $$declare f jsonb;attempt_id uuid:=gen_random_uuid();begin
 f:=pg_temp.fixture();perform pg_temp.claim(f,attempt_id);
 begin perform pg_temp.finish(f,attempt_id,'success',jsonb_build_object('accessToken','new-access','expiresAt',now()+interval '1 hour'));raise exception 'FAIL: audit failure ignored';exception when raise_exception then if SQLERRM<>'Fixture audit failure' then raise;end if;end;
 perform pg_temp.check((select access_token='old-access' and credential_version=1 from public.email_configurations where id=(f->>'c')::uuid),'failed audit rolls back credential replacement');
 perform pg_temp.check((select refresh_status='running' from public.email_token_refreshes where request_id=attempt_id),'failed audit leaves recoverable attempt');
end$$;
drop trigger fixture_audit_failure on public.email_token_refreshes;
create function pg_temp.reject_action() returns trigger language plpgsql as $$begin raise exception 'Fixture action failure';end$$;
create trigger fixture_action_failure before insert on public.shared_action_events for each row when (new.action='email.disconnected') execute function pg_temp.reject_action();
DO $$declare f jsonb;begin
 f:=pg_temp.fixture();
 begin perform public.disconnect_recorded_email((f->>'p')::uuid,(f->>'actor')::uuid,gen_random_uuid(),'microsoft');raise exception 'FAIL: action failure ignored';exception when raise_exception then if SQLERRM<>'Fixture action failure' then raise;end if;end;
 perform pg_temp.check((select access_token='old-access' and sync_enabled and credential_version=1 from public.email_configurations where id=(f->>'c')::uuid),'failed action record rolls back disconnection');
end$$;
drop trigger fixture_action_failure on public.shared_action_events;
select count(*) as passed from checks;
ROLLBACK;
